def dec(b): return gzip.decompress(base64.b64decode(b)).decode("utf-8")

raw = open(PATH, "rb").read()
had_crlf = b"\r\n" in raw
text = raw.replace(b"\r\n", b"\n").decode("utf-8")

applied, skipped = 0, 0
for eo, en in PAIRS:
    old, new = dec(eo), dec(en)
    if text.count(new) >= 1:
        skipped += 1
        continue
    c = text.count(old)
    if c == 0:
        print("❌ 対象が見つかりません（既に別バージョンが当たっている可能性）:")
        print("   " + old[:70].replace("\n", " / "))
        sys.exit(1)
    if c != 1:
        print("❌ 対象が%d箇所ありました（1箇所のみ想定）: %s" % (c, old[:60]))
        sys.exit(1)
    text = text.replace(old, new, 1)
    applied += 1

out = text.replace("\n", "\r\n").encode("utf-8") if had_crlf else text.encode("utf-8")
open(PATH, "wb").write(out)
print("✅ v297 適用完了  (適用 %d / スキップ %d)" % (applied, skipped))
